import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
const PJ = 'C:/Users/user/AppData/Local/Temp/skill-eval-iLekk9';
const require = createRequire(PJ + '/package.json');
const { build } = require('esbuild');
const SP = process.env.SP;
const r = await build({ entryPoints: [PJ + '/out/module.ts'], bundle: true, format: 'esm', platform: 'node', write: false, outfile: SP + '/bundle.mjs', logLevel: 'silent' });
const { publicFields, totalAge, toLookup } = await import(pathToFileURL(SP + '/bundle.mjs').href + '?v=' + Date.now());

// Reference: lodash semantics written inline as an oracle (test-only, not shipped).
const refPublic = (row) => ({ id: row.id, name: row.name });            // lodash pick(row, ['id','name'])
const refTotal = (rows) => rows.reduce((s, r) => s + r.age, 0);        // lodash sumBy(rows,'age'); 0 when empty
const refLookup = (pairs) => { const o = {}; for (const [k, v] of pairs) o[k] = v; return o; } // lodash fromPairs

const names = ['kim', 'lee', 'park', 'choi', 'jung'];
const ri = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const rowGen = () => ({ id: ri(0, 9), name: names[ri(0, 4)], age: ri(18, 60) });
let fails = 0, n = 0;
const eq = (a, b, label) => { n++; const A = JSON.stringify(a), B = JSON.stringify(b); if (A !== B) { fails++; if (fails < 5) console.log('MISMATCH', label, A, B); } };

// Given examples
const ex1 = { id: 5, name: 'jung', age: 42 };
eq(publicFields(ex1), refPublic(ex1), 'pub-ex1');
eq(publicFields({ id: 7, name: 'lee', age: 22 }), { id: 7, name: 'lee' }, 'pub-ex2');
const t1 = [{id:4,name:'lee',age:28},{id:2,name:'kim',age:40},{id:1,name:'choi',age:30},{id:2,name:'lee',age:37},{id:9,name:'jung',age:57}];
eq(totalAge(t1), refTotal(t1), 'tot-ex1');
eq(totalAge([]), 0, 'tot-empty');
eq(toLookup([]), {}, 'lk-empty');
const lk = [["kim",4],["kim",56],["choi",75],["kim",24],["lee",62],["kim",34]];
eq(toLookup(lk), refLookup(lk), 'lk-ex');
console.log('example lookup:', JSON.stringify(toLookup(lk)));

// Random in-range inputs
for (let i = 0; i < 3000; i++) {
  const row = rowGen(); eq(publicFields(row), refPublic(row), 'pub');
  const len = ri(0, 12); const rows = Array.from({ length: len }, rowGen);
  eq(totalAge(rows), refTotal(rows), 'tot');
  const plen = ri(0, 8); const pairs = Array.from({ length: plen }, () => [names[ri(0, 4)], ri(0, 99)]);
  eq(toLookup(pairs), refLookup(pairs), 'lk');
}
console.log(`checks=${n} mismatches=${fails}`);
process.exit(fails ? 1 : 0);
EOF
cd "$PJ" && SP="$(cygpath -w "$SP" 2>/dev/null || echo "$SP")" node "$SP/check.mjs"; echo "EXIT=$?"

